  appendChild(c) { this.children.push(c); c.parent=this; return c; }
  setAttribute(k,v) { this.attributes[k]=v; }
  get options() { return this.children.filter(n=>n.tagName==='option'); }
  get selectedOptions() { return this.options.filter(n=>n.selected); }
  querySelectorAll(selector) { const match=n=>selector.startsWith('.')?n.className.split(' ').includes(selector.slice(1)):n.tagName===selector; return this.children.flatMap(n=>[...(match(n)?[n]:[]),...n.querySelectorAll(selector)]); }
